// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { Callout } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Display/Callout)

figma.connect(Callout, FIGMA_NODE_URL, {
  props: {
    tone: figma.enum('tone', { 'positive': 'positive', 'negative': 'negative', 'brand': 'brand', 'neutral': 'neutral', 'warning': 'warning', 'info': 'info' }),
    label: figma.string('label'),
  },
  example: ({ label, tone }) => (
    <Callout tone={tone}>{label}</Callout>
  ),
});
